&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in multidisciplinary troubleshooting and cross&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‑&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;functional coordination&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
