&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;You’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; shape Veeam’s chann&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;el go-to-market for Data &amp;amp; AI Security, building replicable playbooks&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;, campaigns, and playbooks to uncover &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Securiti&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; business&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;. &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;You’re&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; a channel leader who has built new practices within established partners, drives accountability without friction, and brings deep domain &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;, sales &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;enablement&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;capabilities,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; and executive credibility.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
